before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <array>
#include <iostream>
int main() {
    std::array<int, 2> scores{2, 4};
    for (int score : scores) std::cout << score << " ";
    std::cout << "\n";
}
```

after:
Follow the array through the loop; every visited item exists.

```cpp
#include <array>
#include <iostream>
int main() {
    std::array<int, 2> scores{2, 4};
    for (int score : scores) std::cout << score << " ";
    std::cout << "\n";
}
```
